"""Ports for user notification, including the anti-spam contract.The notification layer is the only part of the system the user experiencescontinuously, which makes it the only part where *volume* is itself a defect. Afirewall that pings forty times a minute trains the user to ignore it, and anignored firewall provides no protection. The debouncer is therefore afirst-class port, not an implementation detail of one adapter.Key design decision: the debounce identity deliberately excludes price. Arecommendation on "Arsenal moneyline at 2.10" and the same recommendation twoseconds later at 2.11 are the *same* advice, so they share a key and the secondis suppressed. Only a material change in expected value, or the expiry of aTTL, re-opens the channel."""from __future__ import annotationsimport abcfrom collections.abc import Sequencefrom datetime import datetimefrom enum import StrEnumfrom types import TracebackTypefrom typing import Any, Protocol, Self, runtime_checkablefrom pydantic import BaseModel, ConfigDict, Fieldfrom betdoc.domain.intelligence.advisor_models import (    ActionType,    RejectionReason,    SessionForecast,    TwinRecommendation,)__all__ = [    "DebounceDecision",    "DebounceReason",    "NotificationChannel",    "NotificationDebouncer",    "NotifierError",    "NotifierUnavailableError",    "RecommendationNotifier",    "recommendation_dedupe_key",]class NotifierError(Exception):    """Base class for notification faults."""    def __init__(self, message: str, **context: Any) -> None:        super().__init__(message)        self.context: dict[str, Any] = contextclass NotifierUnavailableError(NotifierError):    """The channel is unreachable.    Never fatal to the pipeline. A failed notification must not abort an    evaluation cycle, because the recommendation itself is still valid and    still recorded.    """class NotificationChannel(StrEnum):    """Delivery channels. Each is an adapter over the same port."""    CONSOLE = "console"    TELEGRAM = "telegram"    WEBSOCKET = "websocket"    EMAIL = "email"    NULL = "null"class DebounceReason(StrEnum):    """Why a notification was allowed through or suppressed.    Returned as data so suppression is measurable. An unmeasured suppression    rate is indistinguishable from a broken notifier.    """    FIRST_SEEN = "first_seen"    EV_SHIFT_EXCEEDED = "ev_shift_exceeded"    TTL_EXPIRED = "ttl_expired"    ACTION_CHANGED = "action_changed"    CRITICAL_OVERRIDE = "critical_override"    SUPPRESSED_DUPLICATE = "suppressed_duplicate"    SUPPRESSED_RATE_LIMIT = "suppressed_rate_limit"    SUPPRESSED_EXPIRED_RECOMMENDATION = "suppressed_expired_recommendation"    @property    def allows_delivery(self) -> bool:        return not self.value.startswith("suppressed_")class DebounceDecision(BaseModel):    """The debouncer's verdict on one recommendation."""    model_config = ConfigDict(frozen=True, extra="forbid", validate_default=True)    allow: bool    reason: DebounceReason    dedupe_key: str = Field(min_length=1, max_length=512)    previous_notified_at: datetime | None = None    previous_edge_per_unit: float | None = None    current_edge_per_unit: float | None = None    edge_shift_absolute: float | None = Field(        default=None,        description="Absolute change in edge per unit staked since last delivery.",    )    seconds_since_previous: float | None = Field(default=None, ge=0.0)    detail: str = Field(default="", max_length=512)def recommendation_dedupe_key(recommendation: TwinRecommendation) -> str:    """Stable identity for debouncing. Deliberately price-independent.    Composed of channel-relevant identity only: bookmaker, sport, selection    label and action type. Odds and stake are excluded by design, because    including them would mint a fresh key on every tick and defeat the    debouncer entirely, which is precisely the spam loophole being closed.    Rejections are keyed on the reason as well, so a bet that flips from    ``NEGATIVE_EV`` to ``OVEREXPOSURE_ON_SPORT`` is treated as new information    rather than as a repeat.    """    parts: list[str] = [        recommendation.bookmaker.value if recommendation.bookmaker else "unknown",        recommendation.sport_type.value if recommendation.sport_type else "unknown",        recommendation.selection_label or (recommendation.opportunity_id or "unknown"),        recommendation.action_type.value,    ]    if recommendation.rejection_reason is not None:        parts.append(recommendation.rejection_reason.value)    return "|".join(parts)@runtime_checkableclass NotificationDebouncer(Protocol):    """Anti-spam gate applied before every delivery.    Implementations must satisfy four properties:    #. **Bounded memory.** The registry is keyed on unbounded user data, so it       must cap its size and evict. An uncapped registry in a long-running       process is a guaranteed memory leak.    #. **Monotonic timekeeping for intervals.** Wall-clock deltas break under       an NTP step; the TTL must be measured on a monotonic source.    #. **Deterministic given an injected ``now``.** Suppression decisions are       audited, so they must be reproducible.    #. **No I/O.** The gate runs on the hot path of every recommendation.    """    def evaluate(        self, recommendation: TwinRecommendation, *, now: datetime | None = None    ) -> DebounceDecision:        """Decide whether this recommendation may be delivered."""        ...    def record_delivery(        self, recommendation: TwinRecommendation, *, now: datetime | None = None    ) -> None:        """Register a successful delivery so future duplicates are suppressed.        Separate from :meth:`evaluate` on purpose. Recording only after the        channel confirms delivery means a failed send does not suppress the        retry, which would silently drop the alert entirely.        """        ...    def prune(self, *, now: datetime | None = None) -> int:        """Evict expired entries. Returns the number removed."""        ...    @property    def tracked_keys(self) -> int:        """Current registry size. Exposed as a memory-safety SLO."""        ...class RecommendationNotifier(abc.ABC):    """Delivers Twin output to the user through one channel.    Contract:    * **Never raise into the orchestrator.** Translate channel faults into      :class:`NotifierUnavailableError` and let the caller log and continue. A      dead Telegram bot must not stop bet evaluation.    * **Apply the debouncer.** Every adapter runs the gate before delivery and      records only on success.    * **Honour cancellation.** ``asyncio.CancelledError`` propagates so      shutdown is prompt.    """    channel: NotificationChannel    def __init__(self, channel: NotificationChannel, debouncer: NotificationDebouncer) -> None:        self.channel = channel        self._debouncer = debouncer    @property    def debouncer(self) -> NotificationDebouncer:        return self._debouncer    @abc.abstractmethod    async def start(self) -> None:        """Initialise the channel. Must be idempotent."""    @abc.abstractmethod    async def close(self) -> None:        """Tear down cleanly. Must be safe to call twice and after failure."""    async def __aenter__(self) -> Self:        await self.start()        return self    async def __aexit__(        self,        exc_type: type[BaseException] | None,        exc: BaseException | None,        tb: TracebackType | None,    ) -> None:        await self.close()    @abc.abstractmethod    async def notify_recommendation(        self, recommendation: TwinRecommendation, *, now: datetime | None = None    ) -> DebounceDecision:        """Deliver one actionable recommendation, subject to debouncing.        Returns:            The decision taken, so callers can count suppressions.        """    @abc.abstractmethod    async def notify_rejections(        self,        rejections: Sequence[TwinRecommendation],        *,        now: datetime | None = None,    ) -> int:        """Deliver refusals in compact form. Returns the count delivered.        Refusals are rendered as a low-salience batch rather than individual        alerts. They are diagnostic information, and giving them the same        visual weight as an actionable bet is how alert fatigue starts.        """    @abc.abstractmethod    async def notify_forecast(        self, forecast: SessionForecast, *, now: datetime | None = None    ) -> None:        """Deliver the session-level stance."""    async def notify_session(        self,        *,        forecast: SessionForecast,        recommendations: Sequence[TwinRecommendation],        now: datetime | None = None,    ) -> tuple[int, int]:        """Deliver a whole evaluation pass.        Returns:            ``(actionable_delivered, rejections_delivered)``.        """        actionable = [item for item in recommendations if item.action_type.requires_stake]        rejections = [item for item in recommendations if item.action_type is ActionType.PASS]        delivered = 0        for recommendation in actionable:            decision = await self.notify_recommendation(recommendation, now=now)            if decision.allow:                delivered += 1        rejected_shown = await self.notify_rejections(rejections, now=now)        await self.notify_forecast(forecast, now=now)        return delivered, rejected_shown    @staticmethod    def critical_rejections() -> frozenset[RejectionReason]:        """Refusals that always bypass the debouncer.        A breached daily loss limit is not routine diagnostic noise; it is the        firewall halting trading, and the user must see it every time.        """        return frozenset(            {                RejectionReason.DAILY_LOSS_LIMIT_REACHED,                RejectionReason.ACCOUNT_LIMITED_OR_UNAVAILABLE,                RejectionReason.STALE_ACCOUNT_STATE,            }        )